import {images} from './images.js';
import {events,interests,spheres,dateLabel,timeLabel,onDay,initialState,balance,attended,reward,register,cancel,acceptOffer,confirmAttendance,invite,acceptInvitation,guestAttendance,recommended,profileFields,hasProfile,completeRegistration,identityValid,interestFields,completeInterests,contactFields,people,person,withChats,ensureThread,sendText,chatInvited,sendChatInvite,inviteStatus,markRead,unreadTotal,threads,crowd,fewOpen,icsFor,reminderText,shareText,addJoiner,canAddJoiner,openWord} from './model.js';
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 10h18m-14 4h3m4 0h3m-10 3h3',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',bookmark:'M6 3h12v18l-6-4-6 4Z',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-1 5 6 6',close:'m6 6 12 12M6 18 18 6',people:'M14 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM4 21v-2a7 7 0 0 1 14 0v2M18 5a3 3 0 0 1 0 6m2 4a7 7 0 0 1 2 6',building:'M3 21h18M5 21V7l7-4 7 4v14M9 8v2m6-2v2m-6 3v2m6-2v2m-4 6v-3h2v3',check:'m5 12 4 4L19 6',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',filter:'M3 6h18M6 12h12m-9 6h6',logout:'M9 4H4v16h5m5-4 4-4-4-4M8 12h12',chat:'M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-5.4A8 8 0 1 1 21 12Z',send:'M21 3 10 14M21 3l-7 18-4-8-8-4z',back:'M20 12H4m6-6-6 6 6 6'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='tyler-campus-v2';let state,storageError='';try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):initialState();if(state.version!==1||!state.profile||!Array.isArray(state.history)||!Array.isArray(state.saved)||!state.registrations||!state.offer||!Array.isArray(state.profile.interests))throw Error('schema');state=withChats(state);state.profile.interests=state.profile.interests.filter(i=>interests.includes(i))}catch{state=initialState();storageError='Не удалось прочитать сохранённые данные. Заполни форму, чтобы создать профиль заново.'}
let activeChat=null,chatOpen=false;let regStep=0,regDraft={};let category='Все',catalogTab='all',query='',dateFilter='',clubFilter='',feedFilter='Все',calendarDay=2,lastFocus=null;
const $=s=>document.querySelector(s);const modal=$('#modal');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function commit(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{toast('Не удалось сохранить. Проверьте доступ к хранилищу браузера.');return false}}
function update(fn){const n=structuredClone(state);fn(n);return commit(n)}
const navItems=[['home','home','Для тебя'],['events','calendar','Афиша'],['chats','chat','Чаты'],['profile','user','Профиль']];
function page(){return ['home','events','chats','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'home'}
function nav(){return navItems.map(([id,i,t])=>`<a href="#${id}" class="${page()===id?'active':''}" ${page()===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='home'?'<i class="nav-dot"></i>':''}${id==='chats'&&unreadTotal(state)?`<i class="nav-badge" aria-label="Непрочитанных: ${unreadTotal(state)}">${unreadTotal(state)}</i>`:''}</a>`).join('')}
function initials(){return esc(state.profile.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}
function avatars(c){const shown=c.people.slice(0,3);return `<div class="avatars">${shown.map(p=>`<span class="tiny-avatar" title="${esc(p.name)}">${esc(p.initials)}</span>`).join('')}${c.going>shown.length?`<small>+${c.going-shown.length}</small>`:''}</div>`}
function crowdLine(c){return c.going?`<div class="crowd-line"><b>Идут ${c.going}</b> · ${c.open} открыты к знакомству · ${c.shared} с твоими интересами</div>`:`<div class="crowd-line">Пока никто не записался</div>`}
function fewHint(e,c){return `<div class="few-hint"><b>Ты будешь одним из первых</b><p>Мы напомним, когда кто-то присоединится. ${state.registrations[e.id]?'Новые открытые участники появятся в уведомлениях.':'Нажми «Я иду» — и мы сообщим в уведомлениях.'}</p><button class="secondary" data-action="share" data-id="${e.id}">${icon('people')}Позвать друга</button></div>`}
function render(){document.body.classList.toggle('registering',!hasProfile(state));if(!hasProfile(state)){if(modal.open)modal.close();$('#app').innerHTML=registration();return}const p=page();if(p==='chats'){const cur=curChat();if(cur&&chatVisible()&&state.chats[cur]?.unread)commit(markRead(state,cur))}$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#home" class="brand"><img src="icon.svg" alt="">тайлер<span style="color:#86a469">.</span></a><div class="brand-caption">Жизнь вне расписания</div><nav class="nav" aria-label="Главная навигация">${nav()}</nav><div class="side-bottom"><div class="side-tip">${icon('spark')}<b>Твой кампус. Твои люди.</b><p>Пробуй новое, находи компанию<br>и собирай свои впечатления.</p></div><button class="side-user" data-action="profile"><span class="avatar">${initials()}</span><span><b>${esc(state.profile.name)}</b><small>${esc(state.profile.group)} · Личный кабинет</small></span></button></div></aside><div class="workspace"><header class="topbar"><div class="university">${icon('building')}<span>Твой университет</span></div><a class="mobile-brand" href="#home"><img src="icon.svg" alt="">тайлер.</a><div class="top-actions"><span class="demo-pill">ДЕМО</span><button class="top-points" data-action="history" aria-label="История баллов">${icon('spark')}${balance(state)} баллов</button><button class="icon-btn" data-action="notifications" aria-label="Уведомления">${icon('bell')}${!state.notificationsRead?'<i class="notification-dot"></i>':''}</button><button class="avatar" data-action="profile" aria-label="Мой профиль">${initials()}</button></div></header><main class="content ${p==='events'?'catalog':''}">${p==='home'?home():p==='events'?catalog():p==='chats'?chats():profile()}</main></div><nav class="mobile-nav" aria-label="Мобильная навигация">${nav()}</nav></div>`;const sc=$('#chat-scroll');if(sc)sc.scrollTop=sc.scrollHeight}
function heading(title,sub){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="date-label">${icon('calendar')}Воскресенье, 25 октября</div></div>`}
function poster(e){return `<div class="cover-sub">${esc(e.club)} / 2026</div><div class="cover-copy">${esc(e.short).replace('\n','<br>')}</div><div class="poster-art"></div>${images[e.id]?`<img class="cover-photo" src="${images[e.id]}" alt="" loading="lazy">`:''}`}
function card(e,reason=false){const c=crowd(state,e);return `<article class="event-card"><div class="cover-wrap"><button class="card-cover cover-${e.style}" data-action="event" data-id="${e.id}" aria-label="Открыть ${esc(e.title)}">${poster(e)}</button><button class="bookmark ${state.saved.includes(e.id)?'saved':''}" data-action="save" data-id="${e.id}" aria-label="${state.saved.includes(e.id)?'Убрать из сохранённого':'Сохранить мероприятие'}" aria-pressed="${state.saved.includes(e.id)}">${icon(state.saved.includes(e.id)?'check':'bookmark')}</button></div><div class="card-body"><div class="card-meta"><span class="tag">${e.category}</span><span>${dateLabel(e)} · ${timeLabel(e)}</span></div><h3><button class="title-button" data-action="event" data-id="${e.id}">${e.title}</button></h3><div class="event-place">${icon('pin')}${e.place}</div>${crowdLine(c)}<div class="card-footer">${c.going?avatars(c):`<span class="deadline-note">${esc(e.deadline||e.club)}</span>`}<span class="reward">${attended(state,e.id)?'✓ Посещено':state.registrations[e.id]?'✓ Ты идёшь':'+50 баллов'}</span></div>${reason?`<div class="card-reason">${icon('spark')}${e.interests.some(x=>state.profile.interests.includes(x))?'Твой интерес: '+e.interests.filter(x=>state.profile.interests.includes(x))[0]:'Скоро в твоём кампусе'}</div>`:''}</div></article>`}
function offerEvent(){return events.find(e=>e.id===state.offer.eventId)||events[0]}
function hero(){let available=state.offer.status==='available'&&balance(state)<100;let accepted=state.offer.status==='accepted';return `<section class="hero"><div class="hero-content"><div class="hero-tag">${icon('spark')}${available?'ПЕРСОНАЛЬНОЕ ПРЕДЛОЖЕНИЕ':accepted?'ТВОЁ ПЕРСОНАЛЬНОЕ ПРЕДЛОЖЕНИЕ':'ТВОЯ НЕДЕЛЯ В КАМПУСЕ'}</div><h2>${available?'Новый опыт.<br>Вдвое больше баллов.':accepted?'Первый шаг сделан.<br>Увидимся на Дивали!':'Самое интересное —<br>после пар.'}</h2><p>${available?'Начни с события «'+esc(offerEvent().title)+'»: познакомься со своими людьми и получи 100 баллов за участие.':accepted?'Ты в списке участников. Найди компанию и приходи за новыми идеями.':'Открой для себя новые события, интересные идеи и людей, которые тебя понимают.'}</p><button class="primary" data-action="${available||accepted?'offer':'browse'}">${available?'Это мне интересно':accepted?'Посмотреть событие':'Выбрать мероприятие'}${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="star">${available||accepted?'+100':'Т.'}</div><div class="spark">✦</div><div class="mini">${available||accepted?'за новые впечатления':'встретимся в кампусе'}</div></div></section>`}
function home(){let list=recommended(state);if(feedFilter!=='Все')list=list.filter(e=>e.interests.includes(feedFilter));return `${heading('Привет, '+esc(state.profile.name.split(' ')[0])+' <span style="font-size:24px">✳</span>','Хороший день, чтобы попробовать что-то новое.')}<div class="home-layout"><div>${hero()}<div class="section-title"><h2>Тебе может понравиться</h2><a class="text-link" href="#events">Вся афиша ${icon('arrow')}</a></div><div class="interest-row">${['Все',...state.profile.interests].map(c=>`<button class="chip ${feedFilter===c?'active':''}" data-action="feed-filter" data-value="${esc(c)}">${c==='Все'?'✦  Для тебя':esc(c)}</button>`).join('')}<button class="chip" data-action="edit" aria-label="Изменить интересы">+</button></div><div class="event-grid">${list.slice(0,4).map(e=>card(e,true)).join('')||empty()}</div><div class="mini-banner">${icon('people')}<div><b>Вместе интереснее</b><p>Включи открытость к знакомствам и найди компанию на событие.</p></div><button class="text-link" data-action="company">Найти своих ${icon('arrow')}</button></div></div><aside class="rail">${balancePanel()}${calendar()}<section class="panel company-panel"><h3>Не обязательно идти одному</h3><p>В кампусе уже есть люди,<br>которым интересно то же, что и тебе.</p>${avatars(crowd(state,recommended(state)[0]))}<button class="secondary" data-action="company">Найти компанию ${icon('arrow')}</button></section><p class="feed-note">События — по публикациям студорганизаций на 25 октября 2026.<br>Участники и баллы демонстрационные · время московское</p></aside></div>`}
function balancePanel(){const b=balance(state);return `<section class="panel balance-panel"><div class="balance-top">Твоя активность${icon('spark')}</div><div class="balance-number">${b}<span>баллов</span></div><p class="balance-caption">${b?'Каждое событие — часть твоей истории':'Всё начинается с первого шага'}</p><div class="progress"><span style="width:${Math.min(b/300*100,100)}%"></span></div><div class="progress-caption">${b>=300?'Отличный старт — продолжай открывать новое':`${300-b} до отметки 300`}</div><button class="text-link" data-action="history">Как начисляются баллы ${icon('arrow')}</button></section>`}
function calendar(){const list=events.filter(e=>onDay(e,calendarDay)).sort((a,b)=>a.time.localeCompare(b.time));return `<section class="panel"><div class="calendar-head"><h3>Ноябрь 2026</h3><span>${list.length?list.length+' '+(list.length===1?'событие':'событий'):''}</span></div><div class="calendar-grid">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>`<span>${d}</span>`).join('')}${'<i></i>'.repeat(6)}${Array.from({length:30},(_,k)=>k+1).map(d=>`<button class="${calendarDay===d?'selected':''} ${events.some(e=>onDay(e,d))?'has-event':''}" data-action="calendar" data-day="${d}" aria-label="${d} ноября">${d}</button>`).join('')}</div><div class="calendar-events">${list.length?list.slice(0,4).map(e=>`<div class="calendar-event"><i class="event-line"></i><button data-action="event" data-id="${e.id}" style="text-align:left;padding:0"><b>${e.title}</b><small>${timeLabel(e)} · ${e.place}</small></button></div>`).join('')+(list.length>4?`<small class="more-note">и ещё ${list.length-4} в афише</small>`:''):'<div class="calendar-event"><i class="event-line"></i><div><b>Пока без мероприятий</b><small>День для своих планов</small></div></div>'}</div></section>`}
function filtered(){return events.filter(e=>(catalogTab==='all'||catalogTab==='saved'&&state.saved.includes(e.id)||catalogTab==='mine'&&state.registrations[e.id])&&(category==='Все'||e.interests.includes(category))&&(!dateFilter||onDay(e,Number(dateFilter)))&&(!clubFilter||e.club===clubFilter)&&(!query||`${e.title} ${e.desc} ${e.place} ${e.club} ${e.category}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time))}
function empty(){return `<div class="empty">${icon('search')}<h3>Пока ничего не нашлось</h3><p>Попробуй другую тему или сбрось фильтры.</p><button class="secondary" data-action="reset-filters">Показать все события</button></div>`}
function catalog(){const list=filtered();return `${heading('Афиша кампуса','Всё, что происходит в университете. Найди своё.')}<div class="tabs">${[['all','Все события',events.length],['saved','Сохранённые',state.saved.length],['mine','Я иду',Object.keys(state.registrations).length]].map(([id,t,n])=>`<button class="tab ${catalogTab===id?'active':''}" data-action="catalog-tab" data-value="${id}">${t}<span>${n}</span></button>`).join('')}</div><div class="filters"><label class="search-box">${icon('search')}<input id="event-search" type="search" placeholder="Найти событие, тему или клуб" aria-label="Поиск мероприятий" value="${esc(query)}"></label><select id="date-filter" aria-label="Дата"><option value="">Все даты</option>${Array.from({length:30},(_,k)=>k+1).filter(d=>events.some(e=>onDay(e,d))).map(d=>`<option value="${d}" ${dateFilter===String(d)?'selected':''}>${d} ноября</option>`).join('')}</select><select id="club-filter" aria-label="Организатор"><option value="">Все клубы</option>${[...new Set(events.map(e=>e.club))].map(c=>`<option ${clubFilter===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="interest-row">${['Все',...interests].map(c=>`<button class="chip ${category===c?'active':''}" data-action="category" data-value="${c}">${c} <small>${c==='Все'?events.length:events.filter(e=>e.interests.includes(c)).length}</small></button>`).join('')}</div><div id="catalog-results"><p class="results-count">${list.length} из ${events.length} мероприятий · время московское <button class="text-link" style="display:inline;margin-left:10px" data-action="reset-filters">Сбросить фильтры</button></p><div class="event-grid">${list.map(e=>card(e)).join('')||empty()}</div></div>`}
function profile(){const mine=events.filter(e=>state.registrations[e.id]);return `${heading('Мой профиль','Здесь начинается твоя история в кампусе.')}<div class="profile-layout"><div><section class="panel profile-card"><div class="avatar">${initials()}</div><div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.program)}</p><span class="tag">Группа ${esc(state.profile.group)}</span></div><button class="secondary" data-action="edit">${icon('edit')}Редактировать</button></section><section class="panel profile-section"><div class="section-title" style="margin:0 0 15px"><h3 style="margin:0">Мои интересы</h3><button class="text-link" data-action="edit">Изменить</button></div><div class="interest-row" style="margin:0">${state.profile.interests.map(c=>`<span class="chip active">${esc(c)}</span>`).join('')||'<p>Добавь интересы для персональных рекомендаций.</p>'}</div></section><section class="panel profile-section"><h3>Знакомства и контакты</h3><label class="setting"><span><b>Открыт к новым знакомствам</b><small>Будет включено при записи на новые события</small></span><input class="toggle" type="checkbox" id="open-toggle" ${state.profile.open?'checked':''} aria-label="Открытость к знакомствам"></label><label class="setting"><span><b>Показывать мой контакт</b><small>Открытым участникам твоих мероприятий</small></span><input class="toggle" type="checkbox" id="contact-toggle" ${state.profile.contactVisible?'checked':''} aria-label="Видимость контакта"></label><div class="setting"><span><b>Ссылка и телефон</b><small>${esc([state.profile.contact,state.profile.phone].filter(Boolean).join(' · '))||'Пока не указаны'}</small></span><button class="text-link" data-action="edit">${state.profile.contact||state.profile.phone?'Изменить':'Добавить'} ${icon('arrow')}</button></div></section><section class="panel profile-section"><h3>Мои мероприятия <span style="color:#9ca895;font-weight:500">${mine.length}</span></h3>${mine.length?mine.map(e=>`<div class="my-event"><div class="date-square">${e.day}<small>ноя</small></div><div><b>${e.title}</b><p>${e.time} · ${attended(state,e.id)?'Посещено ✓':e.place}</p></div><button class="icon-btn" data-action="event" data-id="${e.id}" aria-label="Открыть мероприятие">${icon('chevron')}</button></div>`).join(''):'<p>Пока нет планов. Самое время выбрать первое событие.</p><a class="text-link" style="margin-top:15px" href="#events">Открыть афишу '+icon('arrow')+'</a>'}</section></div><aside class="profile-right">${balancePanel()}<section class="panel profile-section"><h3>История активности</h3>${historyList()}</section><section class="panel profile-section"><h3>Демонстрационный режим</h3><p>Вымышленные события и участники. Дата показа: 25 октября 2026. Данные сохраняются в этом браузере.</p><button class="secondary full-width" style="margin-top:17px" data-action="demo">Открыть панель демо ${icon('arrow')}</button></section></aside></div>`}
function historyList(){return state.history.length?[...state.history].reverse().map(x=>`<div class="history-row"><div><b>${esc(x.label)}</b><small>Подтверждено в деморежиме</small></div><strong>+${x.amount}</strong></div>`).join(''):'<p style="font-size:11px;color:#99a492">Твои первые баллы ещё впереди.<br>Приходи на событие — начни историю.</p>'}
function openModal(title,body){lastFocus=document.activeElement;modal.innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0}
function eventModal(id,offer=false){const e=events.find(x=>x.id===id);if(!e)return;const reg=state.registrations[id];const c=crowd(state,e);let offerActive=state.offer.eventId===id&&['available','accepted'].includes(state.offer.status)&&(!attended(state,id));openModal('Мероприятие',`<div class="card-cover cover-${e.style}">${poster(e)}</div><h2>${e.title}</h2><span class="tag">${e.club}</span><div class="detail-grid"><div><small>Когда · МСК</small><b>${dateLabel(e)}, ${timeLabel(e)}</b></div><div><small>Где</small><b>${e.location}</b></div><div><small>Продолжительность</small><b>${e.duration}</b></div><div><small>Участие</small><b>${esc(e.cost)}</b></div></div>${e.deadline?`<div class="notice">⏰ ${esc(e.deadline)}</div>`:''}<div class="crowd-box">${crowdLine(c)}${c.going?avatars(c):''}</div>${fewOpen(c)?fewHint(e,c):''}<div class="cal-actions"><button class="secondary" data-action="ics" data-id="${id}">${icon('calendar')}В календарь</button>${fewOpen(c)?'':`<button class="secondary" data-action="share" data-id="${id}">${icon('people')}Позвать друга</button>`}</div><p>${e.desc}</p><p><strong>Что тебя ждёт:</strong> ${e.expect}</p><p class="source-line">Сфера: ${esc(e.interests.join(' · '))}. <a href="${esc(e.source)}" target="_blank" rel="noopener noreferrer">Исходный пост в Telegram</a></p><div class="notice">${offerActive?'✦ Персональное предложение: +100 вместо +50':'✦ +50 баллов'} после подтверждения посещения. ${offerActive?'Прими предложение до начала мероприятия. ':''}Запись сама по себе не начисляет баллы.</div>${reg?`<label class="setting"><span><b>Найти компанию на это событие</b><small>Показывать меня открытым участникам</small></span><input class="toggle" id="event-open" data-id="${id}" type="checkbox" ${reg.open?'checked':''}></label>`:''}<div class="modal-actions">${attended(state,id)?'<span class="secondary">✓ Посещение подтверждено</span>':offerActive&&state.offer.status==='available'?`<button class="primary" data-action="accept-offer">Принять предложение · +100 ${icon('arrow')}</button>`:`<button class="primary" data-action="${reg?'cancel':'register'}" data-id="${id}">${reg?'Отменить запись':'Я иду'} ${icon(reg?'close':'arrow')}</button>`}<button class="secondary" data-action="save-detail" data-id="${id}">${icon(state.saved.includes(id)?'check':'bookmark')}${state.saved.includes(id)?'Сохранено':'Сохранить'}</button></div>${reg?`<button class="text-link" style="margin-top:19px" data-action="company" data-id="${id}">Посмотреть, кто идёт ${icon('arrow')}</button>`:''}${offerActive&&state.offer.status==='available'?'<button class="text-link" style="margin-top:18px;color:#94a08e" data-action="decline-offer">Не сейчас, отказаться от предложения</button>':''}`)}
function identityFields(values={}){return `<div class="form-grid">${[['firstName','Имя','Например, Анна',60,'given-name'],['lastName','Фамилия','Например, Смирнова',60,'family-name'],['group','Группа','Например, ДИ-21',40,'off'],['program','Направление','Например, Дизайн',100,'off']].map(([key,label,placeholder,max,autocomplete])=>`<label class="field">${label}<input name="${key}" type="text" required maxlength="${max}" autocomplete="${autocomplete}" placeholder="${placeholder}" value="${esc(values[key]||'')}"></label>`).join('')}</div>`}
function interestChips(selected=[]){return `<div class="interest-row" style="flex-wrap:wrap">${interests.map(c=>`<label class="chip"><input type="checkbox" name="interest" value="${esc(c)}" ${selected.includes(c)?'checked':''}> ${esc(c)}</label>`).join('')}</div>`}
function registration(){const step=regStep||(identityValid(state)?2:1);const dots=`<div class="reg-steps" aria-label="Шаг ${step} из 2"><i class="${step===1?'on':'done'}"></i><i class="${step===2?'on':''}"></i></div>`;const head=`<div class="brand"><img src="icon.svg" alt="">тайлер<span style="color:#86a469">.</span></div><div class="registration-mark" aria-hidden="true">${step===1?'✳':'♥'}</div>${dots}`;
if(step===1)return `<main class="registration-page"><section class="registration-card" aria-labelledby="registration-title">${head}<p class="registration-eyebrow">ШАГ 1 ИЗ 2 · ТВОЯ ЖИЗНЬ В КАМПУСЕ</p><h1 id="registration-title">Давай знакомиться</h1><p class="registration-intro">Расскажи немного о себе — дальше выберем, что тебе интересно.</p><form id="registration-form">${identityFields(regDraft)}<p id="registration-error" class="registration-error" role="alert"></p><button class="primary full-width" type="submit">Дальше ${icon('arrow')}</button></form><p class="registration-note">Профиль сохранится в этом браузере. На другом устройстве нужно будет заполнить форму заново.</p></section><p class="registration-footer">Твой кампус. Твои люди.</p></main>`;
const p=state.profile,sel=regDraft.interests||p.interests||[];
return `<main class="registration-page"><section class="registration-card" aria-labelledby="registration-title">${head}<p class="registration-eyebrow">ШАГ 2 ИЗ 2 · МОИ ИНТЕРЕСЫ</p><h1 id="registration-title">Что тебе интересно?</h1><p class="registration-intro">Отметь хотя бы один интерес — по ним мы подберём события. Позже всё можно изменить в профиле.</p><form id="interests-form"><div class="field">Мои интересы <small>(нужно выбрать хотя бы один)</small>${interestChips(sel)}</div><div class="reg-contact"><b>Хочешь знакомиться?</b><p>Оставь контакт — открытые к знакомствам участники событий смогут тебе написать. Это необязательно, а показывать контакт или нет, ты решишь сам в профиле.</p><div class="form-grid"><label class="field full">Ссылка на соцсеть или мессенджер<input name="contact" type="text" maxlength="120" inputmode="url" autocomplete="off" placeholder="@username или t.me/username, vk.com/id…" value="${esc(regDraft.contact??p.contact??'')}"></label><label class="field full">Номер телефона<input name="phone" type="tel" maxlength="24" autocomplete="tel" placeholder="+7 900 123-45-67" value="${esc(regDraft.phone??p.phone??'')}"></label></div></div><p id="registration-error" class="registration-error" role="alert"></p><button class="primary full-width" type="submit">Зарегистрироваться ${icon('arrow')}</button><button class="text-link reg-back" type="button" data-action="reg-back">← Назад к данным</button></form></section><p class="registration-footer">Твой кампус. Твои люди.</p></main>`}
function editModal(){openModal('Личные данные',`<form id="profile-form">${identityFields(state.profile)}<div class="form-grid" style="margin-top:16px"><label class="field full">Контакт (необязательно)<input name="contact" maxlength="120" placeholder="@username или HTTPS-ссылка" value="${esc(state.profile.contact)}"></label><label class="field full">Телефон (необязательно)<input name="phone" type="tel" maxlength="24" placeholder="+7 900 123-45-67" value="${esc(state.profile.phone||'')}"></label><div class="field full">Что тебе интересно? <small>(минимум один)</small><div class="interest-row" style="flex-wrap:wrap">${interests.map(c=>`<label class="chip"><input type="checkbox" name="interest" value="${c}" ${state.profile.interests.includes(c)?'checked':''}> ${c}</label>`).join('')}</div></div></div><div class="form-help">Обязательны имя, фамилия, группа, направление и хотя бы один интерес.</div><div class="modal-actions"><button type="submit" class="primary">Сохранить изменения ${icon('check')}</button></div></form>`)}
function companyModal(id){let e=events.find(x=>x.id===id)||events.find(x=>state.registrations[x.id])||events[0];let reg=state.registrations[e.id];const list=crowd(state,e).openPeople.sort((a,b)=>b.interests.filter(x=>state.profile.interests.includes(x)).length-a.interests.filter(x=>state.profile.interests.includes(x)).length);openModal('Найди своих',`<span class="tag">${dateLabel(e)} · ${e.title}</span><p>Открытые участники этого события. Общие интересы помогут начать разговор.</p>${list.length?'':fewHint(e,crowd(state,e))}${!reg?`<div class="notice">Сначала запишись на событие, чтобы предложить компанию.</div><button class="primary" style="margin-top:15px" data-action="register-company" data-id="${e.id}">Я иду ${icon('arrow')}</button>`:''}${list.map(p=>{const shared=p.interests.filter(i=>state.profile.interests.includes(i));const inv=state.invitations[e.id];return `<div class="person"><div class="avatar">${p.initials}</div><div class="person-info"><b>${p.name}</b><small>${p.program}</small><p>${shared.length?'Общее: '+shared.join(', '):'Пока нет общих интересов'}</p><small>Контакт не указан в демоданных</small>${reg?(chatInvited(state,p.id,e.id)?`<div class="sent-note">${icon('check')}<span><b>Приглашение отправлено в чат</b><small>${statusLabel[inviteStatus(state,p.id,e.id)]}</small></span><button class="text-link" data-action="open-chat" data-person="${p.id}">Открыть чат ${icon('arrow')}</button></div>`:`<div class="person-actions"><button class="secondary" data-action="invite" data-id="${e.id}" data-person="${p.id}">Предложить пойти вместе</button><button class="text-link" data-action="open-chat" data-person="${p.id}">Написать</button></div><small class="where">${icon('chat')}Приглашение появится в разделе «Чаты», в переписке с этим человеком</small>`):`<button class="text-link" data-action="open-chat" data-person="${p.id}">Написать ${icon('arrow')}</button>`}</div></div>`}).join('')}<p style="font-size:10px">Все участники вымышлены. Приглашение уходит в раздел «Чаты» и хранится только в этом браузере; ответ Кати можно показать в панели демо.</p>`)}
function notifyExtra(){const rem=events.filter(e=>state.registrations[e.id]&&!attended(state,e.id)).map(e=>`<div class="notification"><span class="tag">Напоминание</span><b style="display:block;margin-top:12px">${esc(reminderText(e,crowd(state,e).open))}</b><p>${dateLabel(e)}${e.time?', '+e.time:''}. Придёт ${e.time?'за час до начала':'накануне'}; то же напоминание лежит в файле «В календарь».</p></div>`).join('');const news=[...(state.notices||[])].reverse().map(n=>`<div class="notification"><span class="tag">Новое</span><p style="margin-top:10px">${esc(n.text)}</p><button class="text-link" data-action="event" data-id="${esc(n.eventId)}">Посмотреть событие ${icon('arrow')}</button></div>`).join('');return news+rem}
function demoModal(){const ids=Object.keys(state.registrations);openModal('Панель демонстрации',`<div class="demo-box">Симуляция · 25 октября 2026, 12:00 МСК<br>Подтверждения ниже не доказывают реальное посещение и не отправляют сообщения.</div>${ids.length?ids.map(id=>{const e=events.find(e=>e.id===id);const inv=state.invitations[id];return `<section class="notification"><b>${e.title}</b><small>${attended(state,id)?'Твоё посещение подтверждено':'Ожидает подтверждения'}</small><div class="modal-actions"><button class="primary" data-action="attendance" data-id="${id}" ${attended(state,id)?'disabled':''}>Подтвердить моё посещение</button>${canAddJoiner(state,id)?`<button class="secondary" data-action="join-demo" data-id="${id}">Демо: присоединился ещё один открытый участник</button>`:''}${inv?.status==='proposed'?`<button class="secondary" data-action="accept-invitation" data-id="${id}">Катя принимает приглашение</button>`:''}${inv?.status==='accepted'&&!inv.guestAttended?`<button class="secondary" data-action="guest-attendance" data-id="${id}">Подтвердить посещение Кати</button>`:''}</div>${inv?`<p>Приглашение: ${{proposed:'предложено',accepted:'принято',completed:'завершено — начислено +30'}[inv.status]}. ${inv.guestAttended?'Катя посетила событие.':''}</p>`:''}</section>`}).join(''):'<p>Сначала запишись хотя бы на одно мероприятие.</p><a class="secondary" href="#events" data-action="close">Открыть афишу</a>'}<div class="notice">Обычное посещение: +50. Принятое персональное предложение: +100 вместо +50. Приглашение Кати: +30 после её принятия и посещения обоими. Повторных начислений нет.</div><button class="text-link danger" style="margin-top:25px" data-action="reset-confirm">Сбросить демонстрацию</button>`)}
const curChat=()=>activeChat&&state.chats[activeChat]?activeChat:threads(state)[0]?.id||null;
const chatVisible=()=>chatOpen||matchMedia('(min-width:651px)').matches;
const chatTime=ts=>new Date(ts).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'});
const statusLabel={proposed:'Ждём ответа',accepted:'Согласие получено',completed:'Сходили вместе',cancelled:'Отменено'};
function openChat(pid){const n=ensureThread(state,pid);if(n!==state&&!commit(n))return;activeChat=pid;chatOpen=true;if(modal.open)modal.close();if(location.hash!=='#chats')location.hash='chats';else render()}
function lastInvite(pid){return [...(state.chats[pid]?.messages||[])].reverse().find(m=>m.type==='invite')}
function preview(t){const m=t.messages.at(-1);if(!m)return 'Новый чат — напиши первое сообщение';const who=m.from==='me'?'Ты: ':'';return m.type==='invite'?`${who}приглашение · ${events.find(e=>e.id===m.eventId)?.title||''}`:who+m.text}
function chatList(list,cur){return `<aside class="chat-list panel" aria-label="Список чатов">${list.map(t=>{const inv=lastInvite(t.id),st=inv&&inviteStatus(state,t.id,inv.eventId),m=t.messages.at(-1);return `<button class="chat-row ${t.id===cur?'active':''}" data-action="chat-select" data-person="${t.id}" ${t.id===cur?'aria-current="true"':''}><span class="avatar">${t.person.initials}</span><span class="chat-row-main"><span class="chat-row-top"><b>${esc(t.person.name)}</b>${m?`<time>${chatTime(m.ts)}</time>`:''}</span><span class="chat-row-prev">${esc(preview(t))}</span>${st?`<span class="pill ${st}">${statusLabel[st]}</span>`:''}</span>${t.unread?`<i class="chat-unread" aria-label="Непрочитанных: ${t.unread}">${t.unread}</i>`:''}</button>`}).join('')}</aside>`}
function inviteCard(pid,m){const p=person(pid),e=events.find(x=>x.id===m.eventId);if(!e)return '';const st=inviteStatus(state,pid,m.eventId),first=esc(p.name.split(' ')[0]);const names=p.guest?['Отправлено','Ответ получен','Идёте вместе']:['Отправлено','Ответ получен'];const done={cancelled:0,proposed:1,accepted:2,completed:3}[st];const caption={proposed:`Приглашение доставлено в этот чат. Ответ придёт сюда же.`,accepted:`${first} согласилась. После события подтвердите посещение — получишь +30 баллов.`,completed:'Сходили вместе: +30 баллов за приглашение.',cancelled:'Приглашение закрыто: ты отменил запись на событие.'}[st];return `<div class="msg me"><div class="invite-card ${st}"><div class="invite-kicker">${icon('calendar')}Приглашение на событие</div><b>${e.title}</b><small>${dateLabel(e)} · ${timeLabel(e)} · ${e.place}</small><p class="invite-text">Привет! Я иду на это событие. Пойдём вместе?</p><ol class="steps">${names.map((n,i)=>`<li class="${i<done?'done':i===done&&st!=='cancelled'?'current':''}"><i>${i<done?'✓':i+1}</i>${n}</li>`).join('')}</ol><p class="invite-where">${caption}</p><button class="text-link" data-action="event" data-id="${e.id}">Открыть событие ${icon('arrow')}</button></div><time>${chatTime(m.ts)}</time></div>`}
function msgHtml(pid,m){if(m.type==='invite')return inviteCard(pid,m);if(m.type==='system')return `<div class="msg-system">${esc(m.text)}</div>`;return `<div class="msg ${m.from==='me'?'me':'them'}"><p>${esc(m.text)}</p><time>${chatTime(m.ts)}</time></div>`}
function chatThread(pid){const p=person(pid),t=state.chats[pid],shared=p.interests.filter(i=>state.profile.interests.includes(i)),first=esc(p.name.split(' ')[0]);return `<section class="chat-thread" aria-label="Чат: ${esc(p.name)}"><header class="chat-head"><button class="icon-btn chat-back" data-action="chat-back" aria-label="Ко всем чатам">${icon('back')}</button><span class="avatar">${p.initials}</span><div class="chat-who"><b>${esc(p.name)}</b><small>${esc(p.program)}</small></div><button class="secondary" data-action="chat-invite-pick" data-person="${pid}">${icon('calendar')}Позвать на событие</button></header><div class="chat-scroll" id="chat-scroll" tabindex="0" role="log" aria-label="Сообщения"><div class="chat-note">${shared.length?'Общее: '+esc(shared.join(', '))+'. ':''}Личная переписка: ${esc(p.name)}. Демо: собеседники вымышлены, переписка хранится только в этом браузере, отвечает только Катя — её ответ включается в панели демо.</div>${t.messages.map(m=>msgHtml(pid,m)).join('')||`<div class="chat-blank">Пока пусто. Напиши сообщение или нажми «Позвать на событие» — приглашение появится здесь.</div>`}</div><form id="chat-form" class="chat-compose" data-person="${pid}"><input id="chat-input" name="text" maxlength="1000" autocomplete="off" placeholder="Сообщение: ${esc(p.name)}" aria-label="Сообщение"><button class="primary" type="submit" aria-label="Отправить">${icon('send')}</button></form></section>`}
function chatEmpty(){return `<div class="chat-empty panel"><div class="chat-empty-ico">${icon('chat')}</div><h2>Здесь будут твои разговоры</h2><p>Когда ты предложишь кому-то пойти вместе, приглашение придёт сюда — в личную переписку с этим человеком. Здесь же появится ответ.</p><ol class="how"><li><i>1</i><span><b>Запишись на событие</b><small>кнопка «Я иду» в афише</small></span></li><li><i>2</i><span><b>Найди своих</b><small>участники, открытые к знакомству</small></span></li><li><i>3</i><span><b>Предложи пойти вместе</b><small>приглашение попадёт в чат, статус виден в карточке</small></span></li></ol><button class="primary" data-action="company">Найти компанию ${icon('arrow')}</button></div>`}
function chats(){const list=threads(state),cur=curChat();return `${heading('Чаты','Приглашения и разговоры с теми, кого ты нашёл на событиях.')}${cur?`<div class="chat-layout ${chatOpen?'open':''}">${chatList(list,cur)}${chatThread(cur)}</div>`:chatEmpty()}`}
function pickEventModal(pid){const p=person(pid),mine=events.filter(e=>state.registrations[e.id]&&!attended(state,e.id));openModal('Позвать на событие',`<div class="send-to"><span class="avatar">${p.initials}</span><span><small>Кому</small><b>${esc(p.name)}</b></span><span class="send-arrow">${icon('arrow')}</span><span><small>Куда придёт</small><b>Ваш личный чат</b></span></div><p>Выбери событие, на которое ты идёшь. Приглашение появится в этом чате, а ответ — там же.</p>${mine.map(e=>{const sent=chatInvited(state,pid,e.id)||(p.guest&&state.invitations[e.id]);return `<div class="my-event"><div class="date-square">${e.day}<small>ноя</small></div><div><b>${e.title}</b><p>${timeLabel(e)} · ${e.place}</p></div><button class="${sent?'secondary':'primary'}" data-action="chat-send-invite" data-person="${pid}" data-id="${e.id}" ${sent?'disabled':''}>${sent?'Уже отправлено':'Отправить'}</button></div>`}).join('')||`<div class="notice">Ты пока никуда не записан. Запишись на событие в афише — и сможешь позвать на него.</div><a class="primary" style="margin-top:15px" href="#events" data-action="close">Открыть афишу</a>`}`)}
document.addEventListener('submit',e=>{if(e.target.id!=='chat-form')return;e.preventDefault();const text=String(new FormData(e.target).get('text')||'').trim();if(!text)return;if(commit(sendText(state,e.target.dataset.person,text,new Date().toISOString()))){render();$('#chat-input')?.focus()}});
function downloadIcs(id){const e=events.find(x=>x.id===id);if(!e)return;const blob=new Blob([icsFor(e,crowd(state,e).open)],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${id}.ics`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл календаря скачан — открой его, чтобы добавить событие')}
async function shareEvent(id){const e=events.find(x=>x.id===id);if(!e)return;const data={title:e.title,text:shareText(e,crowd(state,e)),url:location.href.split('#')[0]+'#events'};if(navigator.share){try{await navigator.share(data);return}catch(err){if(err?.name==='AbortError')return}}try{await navigator.clipboard.writeText(`${data.text} ${data.url}`);toast('Ссылка и приглашение скопированы — отправь другу')}catch{toast(data.text)}}
function resetFilters(){category='Все';query='';dateFilter='';clubFilter='';catalogTab='all';render()}
function saveEvent(id){return update(n=>{n.saved=n.saved.includes(id)?n.saved.filter(x=>x!==id):[...n.saved,id]})}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case'close':modal.close();break;case'reg-back':regStep=1;regDraft={...regDraft,...Object.fromEntries(['firstName','lastName','group','program'].map(k=>[k,state.profile[k]]))};render();break;case'profile':location.hash='profile';break;case'browse':location.hash='events';break;case'event':eventModal(id);break;case'offer':eventModal(state.offer.eventId,true);break;case'save':if(saveEvent(id)){render();toast(state.saved.includes(id)?'Событие сохранено':'Событие убрано из сохранённого')}break;case'save-detail':if(saveEvent(id)){render();eventModal(id)}break;case'feed-filter':feedFilter=el.dataset.value;render();break;case'category':category=el.dataset.value;render();break;case'catalog-tab':catalogTab=el.dataset.value;render();break;case'reset-filters':resetFilters();break;case'calendar':calendarDay=Number(el.dataset.day);render();break;case'edit':editModal();break;case'register':if(commit(register(state,id))){render();eventModal(id);toast('Ты в списке! Баллы начислятся после посещения.')}break;case'cancel':if(commit(cancel(state,id))){render();eventModal(id);toast('Запись отменена')}break;case'accept-offer':if(commit(acceptOffer(state))){render();eventModal(state.offer.eventId);toast('Предложение принято. +100 после посещения!')}break;case'decline-offer':if(update(n=>n.offer.status='declined')){render();modal.close();toast('Предложение отклонено')}break;case'company':companyModal(id);break;case'register-company':if(commit(register(state,id))){render();companyModal(id)}break;case'invite':if(commit(sendChatInvite(state,el.dataset.person||'katya',id))){render();companyModal(id);toast('Приглашение отправлено в чат. Смотри раздел «Чаты».')}break;case'open-chat':openChat(el.dataset.person);break;case'chat-select':activeChat=el.dataset.person;chatOpen=true;render();break;case'chat-back':chatOpen=false;render();break;case'chat-invite-pick':pickEventModal(el.dataset.person);break;case'chat-send-invite':if(commit(sendChatInvite(state,el.dataset.person,id))){modal.close();activeChat=el.dataset.person;chatOpen=true;render();toast('Приглашение отправлено — оно в этом чате')}break;case'history':openModal('Твои баллы',`<div class="balance-number">${balance(state)}<span>баллов</span></div><p>Баллы отражают участие и не имеют денежной ценности.</p><div class="notice">+50 за посещение. +100 по принятому персональному предложению вместо +50. +30 за подходящее приглашение после совместного посещения.</div><h3 style="margin:25px 0 15px">История начислений</h3>${historyList()}`);break;case'notifications':update(n=>n.notificationsRead=true);render();openModal('Уведомления',`<div class="notification"><span class="tag">Для тебя</span><b style="display:block;margin-top:12px">${state.offer.status==='available'?'Новый опыт — двойная награда':state.offer.status==='accepted'?'Предложение принято':'Твоя афиша готова'}</b><p>${state.offer.status==='available'?`Приходи на «${esc(offerEvent().title)}», ${dateLabel(offerEvent())}. По персональному предложению ты получишь 100 баллов после подтверждения посещения.`:`В ноябре в афише ${events.length} событий из каналов студорганизаций. Выбери своё и найди компанию.`}</p><button class="text-link" data-action="event" data-id="${esc(state.offer.eventId)}">Посмотреть событие ${icon('arrow')}</button></div>${notifyExtra()}<p>Уведомления доступны внутри приложения. Системные push не подключены.</p>`);break;case'demo':demoModal();break;case'join-demo':if(commit(addJoiner(state,id))){render();demoModal();toast('Демо: к событию присоединился открытый участник — смотри уведомления')}break;case'ics':downloadIcs(id);break;case'share':shareEvent(id);break;case'attendance':if(commit(confirmAttendance(state,id))){render();demoModal();toast('Демопосещение подтверждено. Баллы начислены.')}break;case'accept-invitation':if(commit(acceptInvitation(state,id))){render();demoModal();toast('Демо: Катя приняла приглашение — ответ в разделе «Чаты»')}break;case'guest-attendance':if(commit(guestAttendance(state,id))){render();demoModal();toast('Демо: посещение Кати подтверждено')}break;case'reset-confirm':openModal('Начать заново?',`<p>Профиль, сохранённые события, записи и баллы в этом браузере будут возвращены к начальным демонстрационным данным.</p><div class="modal-actions"><button class="secondary" data-action="close">Отмена</button><button class="primary" data-action="reset">Сбросить демо</button></div>`);break;case'reset':if(commit(initialState())){modal.close();feedFilter='Все';resetFilters();location.hash='home';toast('Демонстрация восстановлена')}break;}});
document.addEventListener('input',e=>{if(e.target.id==='event-search'){query=e.target.value;const results=filtered();$('#catalog-results').innerHTML=`<p class="results-count">${results.length} из ${events.length} мероприятий · время московское</p><div class="event-grid">${results.map(x=>card(x)).join('')||empty()}</div>`}});
document.addEventListener('change',e=>{const el=e.target;switch(el.id){case'date-filter':dateFilter=el.value;render();break;case'club-filter':clubFilter=el.value;render();break;case'open-toggle':if(!update(n=>n.profile.open=el.checked))el.checked=!el.checked;break;case'contact-toggle':if(el.checked&&!state.profile.contact&&!state.profile.phone){el.checked=false;toast('Сначала добавь контакт в личных данных');editModal()}else if(!update(n=>n.profile.contactVisible=el.checked))el.checked=!el.checked;break;case'event-open':if(!update(n=>n.registrations[el.dataset.id].open=el.checked))el.checked=!el.checked;break;}});
document.addEventListener('submit',e=>{
  const id=e.target.id;if(!['registration-form','interests-form','profile-form'].includes(id))return;
  e.preventDefault();const f=new FormData(e.target),values=Object.fromEntries(f.entries());
  const fail=m=>{if(id==='profile-form')toast(m);else $('#registration-error').textContent=m};
  if(id==='registration-form'){
    let fields;try{fields=profileFields(values)}catch(error){fail(error.message);return}
    const next=completeRegistration(state,fields);if(commit(next)){regDraft={...regDraft,...Object.fromEntries(['firstName','lastName','group','program'].map(k=>[k,fields[k]]))};regStep=2;render();window.scrollTo(0,0)}else fail('Не удалось сохранить профиль. Разреши сохранение данных в браузере и попробуй ещё раз.');
    return;
  }
  const extra={interests:f.getAll('interest'),contact:values.contact||'',phone:values.phone||''};
  if(id==='interests-form'){
    let next;try{next=completeInterests(state,extra)}catch(error){regDraft={...regDraft,...extra};fail(error.message);return}
    if(commit(next)){regStep=0;regDraft={};location.hash='home';render();window.scrollTo(0,0);toast('Добро пожаловать, '+state.profile.firstName+'!')}
    else fail('Не удалось сохранить профиль. Разреши сохранение данных в браузере и попробуй ещё раз.');
    return;
  }
  let fields,more;try{fields=profileFields(values);more=interestFields(extra)}catch(error){toast(error.message);return}
  if(update(n=>{n.profile={...n.profile,...fields,...more};if(!more.contact&&!more.phone)n.profile.contactVisible=false})){feedFilter='Все';modal.close();render();toast('Профиль сохранён. Рекомендации обновлены.')}
});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});modal.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});window.addEventListener('hashchange',()=>{if(modal.open)modal.close();if(page()!=='chats')chatOpen=false;render();window.scrollTo(0,0)});window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){try{const next=e.newValue?JSON.parse(e.newValue):initialState();if(next.version===1){state=withChats(next);modal.close();render()}}catch{toast('Не удалось обновить данные из другой вкладки')}}});render();if(storageError)toast(storageError);
// Обложка без файла убирается (замена inline onerror ради строгой CSP).
document.addEventListener('error',e=>{if(e.target.classList?.contains('cover-photo'))e.target.remove()},true);
